-- Back up the production database before running this additive migration.
CREATE TABLE IF NOT EXISTS users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,name VARCHAR(160) NOT NULL,status ENUM('active','disabled') DEFAULT 'active',stripe_customer_id VARCHAR(80) NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS user_entitlements (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,entitlement_key VARCHAR(120) NOT NULL,status ENUM('active','inactive') DEFAULT 'inactive',source_type ENUM('payment','subscription') NOT NULL,source_id VARCHAR(100) NOT NULL,expires_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY user_entitlement(user_id,entitlement_key),KEY entitlement_source(source_type,source_id),CONSTRAINT fk_entitlement_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS stripe_webhook_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,event_id VARCHAR(100) NOT NULL UNIQUE,event_type VARCHAR(120) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
